  assert.deepEqual(addLine(invoice, { sku: 'DEV-HOUR', qty: -1 }), { ok: false, error: 'QTY_INVALID' });
  assert.deepEqual(addLine(invoice, { sku: 'DEV-HOUR', qty: 2.5 }), { ok: false, error: 'QTY_INVALID' });
});

test('addLine reports UNKNOWN_SKU for unknown product', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const invoice = invoiceResult.value;

  assert.deepEqual(addLine(invoice, { sku: 'FAKE-SKU', qty: 1 }), { ok: false, error: 'UNKNOWN_SKU' });
});

test('removeLine removes a line from the invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 3 },
    ],
  });
  const invoice = invoiceResult.value;

  const result = removeLine(invoice, 'DES-HOUR');
  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 1);
  assert.equal(result.value.lines[0].sku, 'DEV-HOUR');
});

test('removeLine does not mutate the original invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 3 },
    ],
  });
  const invoice = invoiceResult.value;
  const originalLength = invoice.lines.length;

  removeLine(invoice, 'DES-HOUR');

  assert.equal(invoice.lines.length, originalLength);
});

test('removeLine reports NOT_DRAFT for non-draft invoice', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-01-15',
    status: 'sent',
    lines: [
      { sku: 'DES-HOUR', qty: 5, name: 'Design work (hour)', unitPrice: 8500, vatRate: 21 },
      { sku: 'DEV-HOUR', qty: 3, name: 'Development (hour)', unitPrice: 9500, vatRate: 21 },
    ],
  };

  assert.deepEqual(removeLine(invoice, 'DES-HOUR'), { ok: false, error: 'NOT_DRAFT' });
});

test('removeLine reports LINE_NOT_FOUND for unknown SKU', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const invoice = invoiceResult.value;

  assert.deepEqual(removeLine(invoice, 'FAKE-SKU'), { ok: false, error: 'LINE_NOT_FOUND' });
});

test('removeLine reports NO_LINES when removing the last line', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const invoice = invoiceResult.value;

  assert.deepEqual(removeLine(invoice, 'DES-HOUR'), { ok: false, error: 'NO_LINES' });
});

test('addLine and removeLine work together', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  let invoice = invoiceResult.value;

  // Add a line
  let result = addLine(invoice, { sku: 'DEV-HOUR', qty: 3 });
  assert.equal(result.ok, true);
  invoice = result.value;
  assert.equal(invoice.lines.length, 2);

  // Add another
  result = addLine(invoice, { sku: 'COPY-HOUR', qty: 2 });
  assert.equal(result.ok, true);
  invoice = result.value;
  assert.equal(invoice.lines.length, 3);

  // Remove one
  result = removeLine(invoice, 'DEV-HOUR');
  assert.equal(result.ok, true);
  invoice = result.value;
  assert.equal(invoice.lines.length, 2);
  assert.equal(invoice.lines[0].sku, 'DES-HOUR');
  assert.equal(invoice.lines[1].sku, 'COPY-HOUR');
});

test('addLine merges across multiple operations', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  let invoice = invoiceResult.value;

  let result = addLine(invoice, { sku: 'DES-HOUR', qty: 3 });
  invoice = result.value;
  assert.equal(invoice.lines[0].qty, 8);

  result = addLine(invoice, { sku: 'DES-HOUR', qty: 2 });
  invoice = result.value;
  assert.equal(invoice.lines[0].qty, 10);
  assert.equal(invoice.lines.length, 1);
});

test('addLine preserves other line data when merging', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  let invoice = invoiceResult.value;

  const result = addLine(invoice, { sku: 'DES-HOUR', qty: 3 });
  invoice = result.value;

  const line = invoice.lines[0];
  assert.equal(line.sku, 'DES-HOUR');
  assert.equal(line.name, 'Design work (hour)');
  assert.equal(line.unitPrice, 8500);
  assert.equal(line.vatRate, 21);
  assert.equal(line.qty, 8);
});

